#include "nested_test_common.h"
#include "interprocess/container/shared_memory_hash_map.h"
#include "interprocess/container/shared_memory_map.h"
#include "interprocess/sync/posix_mutex.h"
#include <mutex>
using namespace interprocess; using IntMap=SharedMemoryMap<int,int>; using IntHash=SharedMemoryHashMap<int,int>; using MapHash=SharedMemoryMap<int,IntHash>; using HashMap=SharedMemoryHashMap<int,IntMap>;
struct Root{InterprocessMutex mutex; MapHash map_of_hash; HashMap hash_of_map; Root(const SharedMemoryAllocator<std::pair<const int,IntHash>>& a,const SharedMemoryAllocator<std::pair<const int,IntMap>>& b):map_of_hash(a),hash_of_map(8,std::hash<int>{},std::equal_to<int>{},b){}};
int main(){std::string name="nested_map_hash_map_"+std::to_string(getpid()); ManagedSharedMemory::remove(name.c_str()); try{ManagedSharedMemory seg(create_only,name.c_str(),512*1024); auto* r=seg.construct<Root>("RootObject",seg.get_allocator<std::pair<const int,IntHash>>(),seg.get_allocator<std::pair<const int,IntMap>>()); auto ha=seg.get_allocator<std::pair<const int,int>>(); auto ma=seg.get_allocator<std::pair<const int,int>>(); {std::lock_guard<InterprocessMutex> lock(r->mutex); IntHash h(8,ha); h.try_emplace(1,10); r->map_of_hash.emplace(2,std::move(h)); IntMap m(ma); m.try_emplace(3,30); r->hash_of_map.emplace(4,std::move(m));} auto validate=[](Root& root){return root.map_of_hash.at(2).at(1)==10&&root.hash_of_map.at(4).at(3)==30;}; if(!nested_run_lock_and_reader<Root>(name,validate)) return 1; bool ok=seg.get_segment_manager()->check_sanity(); seg.destroy<Root>("RootObject"); ManagedSharedMemory::remove(name.c_str()); if(!ok)return 1; std::cout<<"[nested_map_hash_map_test] SUCCESS"<<std::endl; return 0;}catch(...){ManagedSharedMemory::remove(name.c_str()); return 1;}}
